#!/usr/bin/env python3
"""
SkillSwap Supabase Transition Engine (Termux / Linux / macOS)
=============================================================
Migrates SkillSwap from Firebase Firestore to Supabase Postgres
while preserving Firebase Authentication for user accounts and sign-in.

Usage in Termux / local repository:
    python3 supabase_transition.py
"""

import os
import sys
import json
import base64

print("=" * 65)
print("🚀 SKILLSWAP: MIGRATING FIRESTORE TO SUPABASE POSTGRES")
print("   (Preserving Firebase Authentication)")
print("=" * 65)

ROOT_DIR = os.path.abspath(os.path.dirname(__file__)) if "__file__" in globals() else os.getcwd()
os.chdir(ROOT_DIR)

# 1. Update package.json
print("\n📦 1. Verifying package.json dependencies...")
pkg_path = os.path.join(ROOT_DIR, "package.json")
if os.path.exists(pkg_path):
    with open(pkg_path, "r", encoding="utf-8") as pf:
        pkg = json.load(pf)
    deps = pkg.get("dependencies", {})
    if "@supabase/supabase-js" not in deps:
        deps["@supabase/supabase-js"] = "^2.49.1"
        pkg["dependencies"] = deps
        with open(pkg_path, "w", encoding="utf-8") as pf:
            json.dump(pkg, pf, indent=2)
        print("   ✅ Added @supabase/supabase-js to package.json")
    else:
        print("   ✅ @supabase/supabase-js already present in package.json")

RAW_PAYLOAD = ""
FILES = json.loads(base64.b64decode(RAW_PAYLOAD.encode("ascii")).decode("utf-8"))

print("\n📂 2. Writing updated files...")
for rel_path, content in FILES.items():
    full_path = os.path.join(ROOT_DIR, rel_path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    with open(full_path, "w", encoding="utf-8") as wf:
        wf.write(content)
    print(f"   ✅ Written {rel_path}")

print("\n" + "=" * 65)
print("🎉 MIGRATION COMPLETED SUCCESSFULLY!")
print("=" * 65)
print("""
NEXT STEPS FOR SUPABASE:
1. Open Supabase Dashboard -> SQL Editor (https://supabase.com/dashboard)
2. Run the generated 'SUPABASE_SCHEMA.sql' file to set up all tables,
   RLS policies, and Realtime publications.
3. In your Render Environment Variables, ensure the following are set:
   - SUPABASE_URL
   - SUPABASE_ANON_KEY
   - SUPABASE_SERVICE_ROLE_KEY
   - VITE_SUPABASE_URL
   - VITE_SUPABASE_ANON_KEY
4. Run 'npm install' to ensure @supabase/supabase-js is in node_modules,
   then restart or deploy your server!
""")
